 $('#board').addEventListener('click',ev=>{if(ev.target.id!=='large-map')return;const canvas=ev.target,r=canvas.getBoundingClientRect(),scale=Math.min(r.width/canvas.width,r.height/canvas.height),left=r.left+(r.width-canvas.width*scale)/2,top=r.top+(r.height-canvas.height*scale)/2,m=chartCoords(canvas);let best=null,distance=Infinity;for(const p of mapPlaces()){const d=Math.hypot(ev.clientX-left-m.x(p.x)*scale,ev.clientY-top-m.y(p.z)*scale);if(d<distance){best=p;distance=d;}}if(best&&distance<35)openPlace(best.id);});
