 const oldVisit=c.visit;c.replaceVisit(node=>{if(!node)return;if(node.kind==='message'){bottleCard(node.id.slice(7));return;}if(node.id==='fiestera'){c.world?.life.rescue();return;}if(node.id==='artists'){c.artists();return;}if(node.id==='race'){racePanel();return;}if(node.id==='shop'){c.discover(c.p,'shop');c.save();c.shop();return;}oldVisit(node);if(c.waypoint?.id===node.id)c.waypoint=null;checkAchievements();});
