 if(c.world){let seenBoosts=0,seenHits=0,lastRun=null;c.world.onRaceTick=r=>{if(r!==lastRun){seenBoosts=0;seenHits=0;lastRun=r;}if(r.boosts>seenBoosts){seenBoosts=r.boosts;effect('boost');}if(r.penalties>seenHits){seenHits=r.penalties;effect('splash');}$('#race-hud').classList.toggle('boosting',r.boost>0);$('#race-time').textContent=timeLabel(r.ticks/60*1000);$('#race-checkpoint').textContent=t(`Puerta ${r.checkpoint} / ${RACE_POINTS.length-1}`,`Gate ${r.checkpoint} / ${RACE_POINTS.length-1}`);};c.world.onRaceFinish=raceFinished;c.world.setAdvancedBoat(c.p.model,c.p.accessory);c.world.reduced=settings.reduced;}
 function renderGameButtons(){$('.game-bottom').innerHTML=`<button class="glass icon-btn" data-board="welcome">⚓ ${t('Menú','Menu')}</button><button class="glass icon-btn" data-board="bottles">${t('Dejar botella','Leave bottle')}</button><button class="glass icon-btn" data-action="bottle">🏅 ${t('Progreso','Progress')}</button>`;}renderGameButtons();
 $('#map-wrap').setAttribute('role','button');$('#map-wrap').tabIndex=0;$('#map-wrap').ariaLabel=t('Ampliar carta náutica','Expand nautical chart');$('#map-wrap').addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();openBoard('map');}});
