 const dialogues={history:[['¡Eh, capitán!','Ahoy, captain!'],['Se ha perdido la BOIA Fiestera. Búscala y llévala a la última isla.','BOIA Fiestera is lost. Find her and take her to the final island.'],['Por el camino hay descuentos, monedas y secretos. BOIA da espacio a todos los sonidos.','There are discounts, coins and secrets along the way. BOIA makes room for every sound.'],['Toca el mapa para ampliarlo. Mantenlo pulsado para moverlo.','Tap the map to expand it. Hold it to move it.'],['¿Te pierdes? En el ancla tienes ayuda, tu Carnet, logros y tu barco.','Lost? The anchor holds help, your Card, achievements and your boat.']],fiestera:[['¿Se han ido?','Have they gone?'],['¡Menos mal! La fiesta está en la última isla.','What a relief! The party is on the final island.'],['¿Me llevas, capitán?','Will you take me, captain?']],castaway:[['Mi barco está regular… ¡pero mi outfit está listo!','My boat is a mess… but my outfit is ready!'],['¿Me acercas? Está a punto de empezar BOIA. Te guardo un descuento.','Can you help? BOIA is about to start. I have a discount for you.']]};
 let speaking=null,speechStep=0,speechTime=0,speechShown='',nearId=null;const completedTalks=new Set();
 function drawSpeech(text,action=''){bubble.hidden=false;const key=text+action;if(key===speechShown)return;speechShown=key;bubble.innerHTML=`<small>${speaking==='fiestera'?'BOIA FIESTERA':speaking==='history'?'BOIA / 01':t('DESDE EL MAR','FROM THE SEA')}</small><p>${e(text)}</p>${action}`;bubble.hidden=false;effect('plop');}
 function notify(es,en,label){achievementQueue.push({es,en,points:0,label});showAchievement();}
 if(c.world){const w=c.world;w.dayNight=settings.dayNight;w.life.setProgress(c.p);const onNearby=w.onNearby;w.onNearby=n=>{onNearby(n);if(n&&n.kind!=='message'&&n.id!=='race'){
 const fresh=c.discover(c.p,n.id);if(fresh){if(n.kind==='buoy'){earn('first-buoy');if(NODES.filter(a=>a.kind==='buoy').every(a=>c.p.discovered.includes(a.id)))earn('all-buoys');}if(EVENTS.every(a=>c.p.discovered.includes(a.id)))earn('all-islands');c.save();if(!ACHIEVEMENTS.some(a=>a.id==='find-'+n.id))notify(t('Descubierto: ','Discovered: ')+placeName(n),t('Descubierto: ','Discovered: ')+placeName(n),t('CARTA ACTUALIZADA','CHART UPDATED'));}
 if(n.kind==='event'){$('#interact').innerHTML=`<small>${e(placeName(n))} · ${t('HAS LLEGADO','YOU HAVE ARRIVED')}</small><strong>${t('EXPLORAR LA ISLA','EXPLORE THE ISLAND')} ↗</strong>`;}
 }
 const id=n?.id;if(id!==nearId){nearId=id;speaking=dialogues[id]&&!completedTalks.has(id)?id:null;speechStep=0;speechTime=0;speechShown='';bubble.hidden=true;}
 if(id==='fiestera'){$('#interact').hidden=true;if(w.life.state!=='lost')speaking=null;}
 if(id==='history'&&speaking)$('#interact').hidden=true;
 };
 w.onAdventureFrame=({dt,s,active})=>{if(!active){bubble.hidden=true;return;}$('#tutorial').hidden=true;if(speaking){const n=NODES.find(n=>n.id===speaking);if(!n)return;speechTime+=dt;if(speechTime>4.5&&speechStep<dialogues[speaking].length-1){speechStep++;speechTime=0;}const last=speechStep===dialogues[speaking].length-1;const action=last&&speaking==='fiestera'?`<button data-rescue-fiestera>${t('¡Sube a bordo!','Jump aboard!')} ⛵</button>`:last&&speaking==='history'?`<button data-story>${t('La filosofía BOIA','The BOIA philosophy')} ↗</button>`:'';drawSpeech(t(...dialogues[speaking][speechStep]),action);const pos=w.projectPoint(n.x,3,n.z);bubble.style.left=Math.max(12,Math.min(innerWidth-300,pos.x-145))+'px';bubble.style.top=Math.max(145,Math.min(innerHeight-240,pos.y-170))+'px';if(last&&speaking==='history')$('.board-toggle')?.classList.add('anchor-pulse');if(last&&speechTime>9&&speaking!=='fiestera'){completedTalks.add(speaking);speaking=null;bubble.hidden=true;$('.board-toggle')?.classList.remove('anchor-pulse');}}else if(!w.moved&&s.z>30){drawSpeech(t('Toca el barco y arrastra para navegar.','Touch the boat and drag to sail.'));const pos=w.screenBoat();bubble.style.left=Math.max(12,Math.min(innerWidth-300,pos.x-145))+'px';bubble.style.top=Math.max(145,pos.y-145)+'px';}else bubble.hidden=true;};
 let lastReaction=0;w.onLife=event=>{if(event.type==='rescued'){c.p.mission='aboard';earn('rescue-fiestera');c.waypoint=EVENTS[2];speaking=null;completedTalks.add('fiestera');bubble.hidden=true;effect('rescue');c.save();}if(event.type==='delivered'){c.p.mission='delivered';earn('deliver-fiestera');c.save();effect('rescue');notify('¡Lo hemos conseguido! La aventura continúa.','We made it! The adventure continues.',t('FIESTERA HA LLEGADO','FIESTERA HAS ARRIVED'));}if(event.type==='find'){const pts=addSeaFind(c.p,device,event.kind,event.amount);if(event.rare){earn('find-rare');if(!c.p.owned.includes('accessory'))c.p.owned.push('accessory');}normalisePoints(c.p);c.save();effect('coin');clearTimeout(findTimer);findToast.hidden=false;findToast.textContent=`+${pts} ◇ · `+({wood:t('Restos a la deriva','Drifting wood'),chest:t('¡Un tesoro!','A treasure!'),dolphin:t('Gracias, compañero','Thanks, friend'),whirlpool:t('Remolino superado','Whirlpool mastered')})[event.kind];findTimer=setTimeout(()=>findToast.hidden=true,1900);if(c.p.mission==='aboard'&&w.elapsed-lastReaction>55){lastReaction=w.elapsed;c.toast(t('Fiestera: ¡Esta sí que es una ruta con ritmo!','Fiestera: Now this route has rhythm!'));}}};
 }
