 const map=$('#map-wrap');let drag=null,hold=null,skipMapClick=false;try{map.dataset.corner=localStorage.getItem('boia.map.corner')||'bottom-left';}catch{map.dataset.corner='bottom-left';}
 map.addEventListener('pointerdown',ev=>{if(ev.button!==0)return;drag={id:ev.pointerId,x:ev.clientX,y:ev.clientY,active:false,rect:map.getBoundingClientRect()};hold=setTimeout(()=>{if(!drag)return;drag.active=true;map.setPointerCapture(drag.id);map.classList.add('dragging');effect('plop');},500);});
