 function endMapDrag(ev){clearTimeout(hold);if(drag?.active){skipMapClick=true;map.dataset.corner=(ev.clientY<innerHeight/2?'top':'bottom')+'-'+(ev.clientX<innerWidth/2?'left':'right');map.style.transform='';map.classList.remove('dragging');try{localStorage.setItem('boia.map.corner',map.dataset.corner);}catch{}setTimeout(()=>skipMapClick=false,300);}drag=null;}
